useIdentityVerificationCredentials.code:
import { useRef, useState } from "react";
import {
    CrossmintIdentityVerification,
    type IdentityVerificationAppearance,
    useIdentityVerificationCredentials,
} from "@crossmint/client-sdk-react-ui";

// Mount one step per order, for example with key={order.orderId}, so the next order starts open.
function VerificationStep({ appearance }: { appearance?: IdentityVerificationAppearance }) {
    const credentials = useIdentityVerificationCredentials();
    // The order moves on before the flow shows its result, so keep the last credentials
    // and close the step on onComplete or onCancel.
    const lastCredentials = useRef(credentials);
    lastCredentials.current = credentials ?? lastCredentials.current;
    const [closed, setClosed] = useState(false);

    if (closed || lastCredentials.current == null) {
        return null;
    }

    return (
        <CrossmintIdentityVerification
            credentials={lastCredentials.current}
            appearance={appearance}
            onComplete={({ status }) => {
                console.log(status);
                setClosed(true);
            }}
            onCancel={() => setClosed(true)}
        />
    );
}

