CrossmintProtectedInput.code:
import { useRef, useState } from "react";
import {
    CrossmintProvider,
    CrossmintProtectedInput,
    type CrossmintProtectedInputRef,
    type ProtectedInputField,
} from "@crossmint/client-sdk-react-ui";

type Props = {
    apiKey: string;
    jwt: string;
    field: ProtectedInputField;
    onCollected: (answer: { protectedInputId: string }) => Promise<void>;
};

export function ProtectedField({ apiKey, jwt, field, onCollected }: Props) {
    const ref = useRef<CrossmintProtectedInputRef>(null);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState("");

    async function collect() {
        if (busy || ref.current === null) {
            return;
        }
        setBusy(true);
        setError("");
        try {
            const result = await ref.current.collect();
            if (result.status !== "collected") {
                setError(result.message);
                return;
            }
            await onCollected(result.input);
        } catch {
            setError("Could not confirm submission. Retry the same message.");
        } finally {
            setBusy(false);
        }
    }

    return (
        <CrossmintProvider apiKey={apiKey}>
            <div>{field.label}</div>
            <CrossmintProtectedInput
                ref={ref}
                jwt={jwt}
                field={field}
                disabled={busy}
                invalid={error !== ""}
            />
            {error !== "" && <p role="alert">{error}</p>}
            <button type="button" disabled={busy} onClick={collect}>
                Continue
            </button>
        </CrossmintProvider>
    );
}

